41	async fn spawn_stalled_response() -> (String, Arc<Notify>, tokio::task::JoinHandle<()>) {
42	    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
43	    let addr = listener.local_addr().unwrap();
44	    let release = Arc::new(Notify::new());
45	    let release_for_server = Arc::clone(&release);
46	    let server = tokio::spawn(async move {
47	        let (mut socket, _) = listener.accept().await.unwrap();
48	        let mut request = [0u8; 4096];
49	        let _ = socket.read(&mut request).await;
50	        socket
51	            .write_all(
52	                b"HTTP/1.1 200 OK\r\n\
53	                  Content-Length: 1048576\r\n\
54	                  Content-Type: application/octet-stream\r\n\
55	                  Connection: close\r\n\
56	                  \r\n",
57	            )
58	            .await
59	            .unwrap();
60	        socket.write_all(&vec![0xAA; 64 * 1024]).await.unwrap();
61	        socket.flush().await.unwrap();
62	        release_for_server.notified().await;
63	    });
64	    (format!("http://{addr}/foo/-/foo-1.0.0.tgz"), release, server)
65	}
