121	#[tokio::test]
122	async fn cancelling_in_flight_response_body_removes_tmp_file() {
123	    let expected_bytes = vec![0xAA; 1024 * 1024];
124	    let integrity = parse_integrity(&sha512_integrity(&expected_bytes)).unwrap();
125	    let (url, release, server) = spawn_stalled_response().await;
126	    let response = reqwest::get(url).await.unwrap();
127	
128	    let tmp = TempDir::new().unwrap();
129	    let cache = tmp.path().join("cache");
130	    let storage = Storage::new(&HostedStoreConfig::Fs, tmp.path().join("hosted"), cache.clone());
131	    let name = PackageName::parse("foo").unwrap();
132	    let write = storage.open_cached_tarball_tmp(&name, "foo-1.0.0.tgz").await.unwrap();
133	
134	    let download = tokio::spawn(async move {
135	        download_verified_to_cache(response, write, &integrity, u64::MAX).await
136	    });
137	    let package_dir = cache.join("foo");
138	    let in_flight = await_nonempty_tarball_tmp(&package_dir).await;
139	    assert_eq!(in_flight.len(), 1, "expected one in-flight tarball writer");
140	
141	    download.abort();
142	    assert!(download.await.unwrap_err().is_cancelled());
143	    assert!(tarball_tmp_entries(&package_dir).is_empty());
144	    assert!(!package_dir.join("foo-1.0.0.tgz").exists());
145	
146	    release.notify_one();
147	    server.await.unwrap();
148	}
