/// State threaded through the tee stream returned by
/// [`stream_verified_to_cache`]. Dropping it (client disconnect, or the
/// body being dropped before end-of-stream) drops `write`, whose [`Drop`]
/// removes the temp file — nothing unverified is left behind.
struct TeeState {
    upstream: Pin<Box<dyn Stream<Item = reqwest::Result<Bytes>> + Send>>,
    write: TarballWrite,
    checker: IntegrityChecker,
    written: u64,
    max_bytes: u64,
}

/// Stream an upstream response to the client while teeing every byte into
/// the cache temp file and hashing it. Returns immediately with a [`Body`]
/// that yields chunks as they arrive upstream; the status line is already
/// `200 OK` by the time verification happens.
///
/// The declared `Content-Length` is the only synchronous gate: if it
/// exceeds `max_bytes` the call returns [`TarballStreamError::TooLarge`]
/// before any byte is streamed and `write` is dropped (its [`Drop`] removes
/// the temp file). Otherwise SRI is checked at end-of-stream:
///
/// * match — the temp file is promoted to the cache;
/// * mismatch — the (tampered) bytes have already reached the client under
///   `200 OK`; the temp file is abandoned so nothing unverified is cached,
///   and the client's own SRI check is what rejects them;
/// * an upstream error or truncation surfaces as an error at the body level
///   and the incomplete temp file is abandoned.
pub fn stream_verified_to_cache(
    response: reqwest::Response,
    write: TarballWrite,
    integrity: &Integrity,
    max_bytes: u64,
) -> Result<Body, TarballStreamError> {
    if let Some(received) = response.content_length()
        && received > max_bytes
    {
        // `write` is dropped as this returns, and its `Drop` removes the
        // temp file before any streaming begins.
        return Err(TarballStreamError::TooLarge { limit: max_bytes, received });
    }
    let checker = integrity_checker(integrity).map_err(TarballStreamError::Integrity)?;
    let state = TeeState {
        upstream: Box::pin(response.bytes_stream()),
        write,
        checker,
        written: 0,
        max_bytes,
    };
    let stream = stream::unfold(Some(state), |state| async move {
        let mut state = state?;
        match state.upstream.next().await {
            Some(Ok(chunk)) => {
                let received = state.written.saturating_add(chunk.len() as u64);
                if received > state.max_bytes {
                    return Some((Err(oversized_body_error(state.max_bytes, received)), None));
                }
                if let Err(err) = state.write.write_all(&chunk).await {
                    return Some((Err(err), None));
                }
                state.checker.input(&chunk);
                state.written = received;
                Some((Ok::<Bytes, io::Error>(chunk), Some(state)))
            }
            // The status line was sent with the first bytes, so a mid-stream
            // failure can only surface as a body-level error. `state` (and its
            // `write`) drops here, abandoning the incomplete temp file.
            Some(Err(source)) => Some((Err(io::Error::other(source)), None)),
            None => {
                let TeeState { write, checker, .. } = state;
                match checker.result() {
                    // Promote the verified bytes only after the full body has
                    // been both streamed and hashed.
                    Ok(_) => match write.finalize().await {
                        Ok(()) => None,
                        Err(err) => Some((Err(err), None)),
                    },
                    // Tampered bytes already reached the client under 200 OK;
                    // dropping `write` abandons the temp file so they are never
                    // cached. End the body cleanly — the client's SRI check rejects.
                    Err(_) => {
                        drop(write);
                        None
                    }
                }
            }
        }
    });
    Ok(Body::from_stream(stream))
}

fn oversized_body_error(limit: u64, received: u64) -> io::Error {
    io::Error::other(format!(
        "upstream tarball exceeded the {limit}-byte limit ({received} bytes received)"
    ))
}

