152	/// State threaded through the tee stream returned by
153	/// [`stream_verified_to_cache`]. Dropping it (client disconnect, or the
154	/// body being dropped before end-of-stream) drops `write`, whose [`Drop`]
155	/// removes the temp file — nothing unverified is left behind.
156	struct TeeState {
157	    upstream: Pin<Box<dyn Stream<Item = reqwest::Result<Bytes>> + Send>>,
158	    write: TarballWrite,
159	    checker: IntegrityChecker,
160	    written: u64,
161	    max_bytes: u64,
162	}
