164	/// Stream an upstream response to the client while teeing every byte into
165	/// the cache temp file and hashing it. Returns immediately with a [`Body`]
166	/// that yields chunks as they arrive upstream; the status line is already
167	/// `200 OK` by the time verification happens.
168	///
169	/// The declared `Content-Length` is the only synchronous gate: if it
170	/// exceeds `max_bytes` the call returns [`TarballStreamError::TooLarge`]
171	/// before any byte is streamed and `write` is dropped (its [`Drop`] removes
172	/// the temp file). Otherwise SRI is checked at end-of-stream:
173	///
174	/// * match — the temp file is promoted to the cache;
175	/// * mismatch — the (tampered) bytes have already reached the client under
176	///   `200 OK`; the temp file is abandoned so nothing unverified is cached,
177	///   and the client's own SRI check is what rejects them;
178	/// * an upstream error or truncation surfaces as an error at the body level
179	///   and the incomplete temp file is abandoned.
180	pub fn stream_verified_to_cache(
181	    response: reqwest::Response,
182	    write: TarballWrite,
183	    integrity: &Integrity,
184	    max_bytes: u64,
185	) -> Result<Body, TarballStreamError> {
186	    if let Some(received) = response.content_length()
187	        && received > max_bytes
188	    {
189	        // `write` is dropped as this returns, and its `Drop` removes the
190	        // temp file before any streaming begins.
191	        return Err(TarballStreamError::TooLarge { limit: max_bytes, received });
192	    }
193	    let checker = integrity_checker(integrity).map_err(TarballStreamError::Integrity)?;
194	    let state = TeeState {
195	        upstream: Box::pin(response.bytes_stream()),
196	        write,
197	        checker,
198	        written: 0,
199	        max_bytes,
200	    };
201	    let stream = stream::unfold(Some(state), |state| async move {
202	        let mut state = state?;
203	        match state.upstream.next().await {
204	            Some(Ok(chunk)) => {
205	                let received = state.written.saturating_add(chunk.len() as u64);
206	                if received > state.max_bytes {
207	                    return Some((Err(oversized_body_error(state.max_bytes, received)), None));
208	                }
209	                if let Err(err) = state.write.write_all(&chunk).await {
210	                    return Some((Err(err), None));
211	                }
212	                state.checker.input(&chunk);
213	                state.written = received;
214	                Some((Ok::<Bytes, io::Error>(chunk), Some(state)))
215	            }
216	            // The status line was sent with the first bytes, so a mid-stream
217	            // failure can only surface as a body-level error. `state` (and its
218	            // `write`) drops here, abandoning the incomplete temp file.
219	            Some(Err(source)) => Some((Err(io::Error::other(source)), None)),
220	            None => {
221	                let TeeState { write, checker, .. } = state;
222	                match checker.result() {
223	                    // Promote the verified bytes only after the full body has
224	                    // been both streamed and hashed.
225	                    Ok(_) => match write.finalize().await {
226	                        Ok(()) => None,
227	                        Err(err) => Some((Err(err), None)),
228	                    },
229	                    // Tampered bytes already reached the client under 200 OK;
230	                    // dropping `write` abandons the temp file so they are never
231	                    // cached. End the body cleanly — the client's SRI check rejects.
232	                    Err(_) => {
233	                        drop(write);
234	                        None
235	                    }
236	                }
237	            }
238	        }
239	    });
240	    Ok(Body::from_stream(stream))
241	}
